select delivered_quarter, shipped_month, avg_cost, total_cost from (select quarter(delivered_date) as delivered_quarter, date_trunc('MONTH', shipped_date) as shipped_month, avg(cost) as avg_cost, sum(cost) as total_cost from shipments where delivered_date >= '2023-09-01' group by quarter(delivered_date), date_trunc('MONTH', shipped_date)) as t where total_cost > 230 order by 1 desc, total_cost desc;
